'use strict';
const $=id=>document.getElementById(id);
const canvas=$('game'),ctx=canvas.getContext('2d');
const game={w:2200,h:1400,width:1000,height:700,camera:new Vec(700,500),zoom:1,autoZoom:false,keys:new Set(),target:new Vec(1100,700),fish:[],enemies:[],jellies:[],obstacles:[],food:[],particles:[],player:null,params:{maxSpeed:115,maxForce:160,vision:180,prediction:.55,separation:1.5,alignment:.8,cohesion:.65,population:65,currents:false,genetic:true,trails:false,vectors:false},mode:'flock',state:'menu',sandbox:false,score:0,eaten:0,health:100,boost:100,level:1,time:0,ambientTime:0,lastEat:-10,combo:0,best:0,generation:1,spawnTimer:0,boosting:false,mouse:new Vec(),pointerActive:false};
try{game.best=Number(localStorage.getItem('abyss-best'))||0;}catch{}
const fishGrid=new SpatialGrid(128);
const dust=Array.from({length:48},()=>({x:Math.random(),y:Math.random(),r:rand(.4,2),speed:rand(.5,2)}));
let sound=false,audio=null,toastTimer=null,frameTime=0,uiTimer=0,fps=60,bestSaveTimer=null,bestDirty=false;
const graphics={economy:false,glow:false,pixelBudget:1600000};
try{graphics.economy=localStorage.getItem('abyss-economy')==='1';}catch{}
function chirp(type='eat'){if(!sound)return;try{if(!audio)audio=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();const osc=audio.createOscillator(),gain=audio.createGain();osc.connect(gain);gain.connect(audio.destination);osc.type='sine';const t=audio.currentTime;osc.frequency.setValueAtTime(type==='eat'?500:type==='hurt'?110:700,t);osc.frequency.exponentialRampToValueAtTime(type==='eat'?950:type==='hurt'?60:1200,t+.12);gain.gain.setValueAtTime(.045,t);gain.gain.exponentialRampToValueAtTime(.001,t+.18);osc.start();osc.stop(t+.2);}catch{}}
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2700);}
function show(id,visible){$(id).classList.toggle('hidden',!visible);}
function safePosition(margin=80){for(let i=0;i<100;i++){const p=new Vec(rand(margin,game.w-margin),rand(margin,game.h-margin));if(game.obstacles.every(o=>p.dist(o.pos)>o.radius+60))return p;}return new Vec(game.w/2,game.h/2);}
function reset(sandbox=false,start=false){game.sandbox=sandbox;game.score=0;game.eaten=0;game.health=100;game.boost=100;game.level=1;game.time=0;game.combo=0;game.lastEat=-10;game.generation=1;game.mode='flock';game.spawnTimer=0;game.state=start?'playing':'menu';game.keys.clear();game.obstacles=[new Obstacle(450,430,72),new Obstacle(870,950,88),new Obstacle(1470,680,75),new Obstacle(1830,340,90),new Obstacle(1690,1130,60),new Obstacle(300,1110,65),new Obstacle(1100,210,58)];game.player=new Shark(1100,650,true);game.player.vel=new Vec();game.target=game.player.pos.copy();game.camera=new Vec(1100-game.width*.5,650-game.height*.5);game.fish=[];for(let i=0;i<game.params.population;i++){const center=new Vec(350+(i%4)*460,300+Math.floor(i%12/4)*350);const p=Vec.add(center,new Vec(rand(-120,120),rand(-100,100)));const f=new Fish(clamp(p.x,50,game.w-50),clamp(p.y,50,game.h-50),i%3);f.vel=Vec.fromAngle(i%4).mult(50);f.resolveObstacles(game.obstacles);game.fish.push(f);}game.enemies=[new Shark(1700,250),new Shark(350,850),new Shark(1900,1050)];game.jellies=Array.from({length:8},()=>{const p=safePosition();return new Jelly(p.x,p.y);});game.food=Array.from({length:36},()=>safePosition());game.particles=[];game.path=[new Vec(230,230),new Vec(1800,170),new Vec(2020,800),new Vec(1500,1220),new Vec(350,1230),new Vec(180,650)];show('welcome',!start);show('endScreen',false);show('pauseScreen',false);$('behavior').value='flock';updateHUD();}
function start(sandbox=false){reset(sandbox,true);$('game').focus();toast(sandbox?'Exploration libre · aucune perte de vitalité':'Objectif : 25 poissons · 1 000 points · 90 secondes');}
function pause(){if(game.state==='playing'){game.state='paused';show('pauseScreen',true);$('pauseBtn').textContent='▶';}else if(game.state==='paused'){game.state='playing';show('pauseScreen',false);$('pauseBtn').textContent='Ⅱ';}}
function finish(won){game.state='ended';show('endScreen',true);$('endTag').textContent=won?'EXPÉDITION ACCOMPLIE':'FIN DE L’EXPÉDITION';$('endTitle').textContent=won?'Le récif a son roi.':'Retour à la surface.';$('endText').textContent=won?'Les trois objectifs sont atteints. Tu maîtrises les eaux du récif.':`${game.eaten} poissons capturés en ${Math.floor(game.time)} secondes. Replonge et affine ta chasse !`;$('endScore').textContent=game.score.toLocaleString('fr-FR');saveBest();}
function saveBest(){if(game.score>game.best){game.best=game.score;bestDirty=true;if(bestSaveTimer===null)bestSaveTimer=setTimeout(flushBest,750);}}
function flushBest(){if(bestSaveTimer!==null){clearTimeout(bestSaveTimer);bestSaveTimer=null;}if(bestDirty){try{localStorage.setItem('abyss-best',game.best);bestDirty=false;}catch{}}}
window.addEventListener('pagehide',flushBest);
document.addEventListener('visibilitychange',()=>{if(document.hidden)flushBest();});
function setMode(mode){game.mode=mode;$('behavior').value=mode;toast({flock:'Boids · séparation, alignement, cohésion',leader:'Escorte · arrivée derrière le leader et dégagement devant',snake:'Snake · chaque poisson suit le précédent',path:'Migration · projection scalaire sur le chemin',seek:'Seek · attraction vers le requin',flee:'Flee · fuite de la position actuelle',evade:'Evade · anticipation de la position du prédateur',wander:'Wander · déambulation sur un cercle projeté'}[mode]);}
function emit(x,y,color,text=''){if(game.particles.length>100&&!text)return;game.particles.push(new Particle(x,y,color,text));for(let i=0;i<(graphics.economy?2:4);i++)game.particles.push(new Particle(x,y,color));}
function eatFish(f){game.eaten++;game.combo=game.time-game.lastEat<2.5?Math.min(5,game.combo+1):1;game.lastEat=game.time;const points=[30,45,70][f.type]*game.combo;game.score+=points;game.health=clamp(game.health+8,0,100);emit(f.pos.x,f.pos.y,['#8debd9','#faaf80','#f7d585'][f.type],`+${points}`);chirp();const next=Math.min(5,1+Math.floor(game.eaten/10));if(next>game.level){game.level=next;game.player.radius=24+(next-1)*5;toast(`Croissance ${next} · Ton requin grandit !`);chirp('level');}saveBest();}
function hurt(amount){if(game.sandbox||game.player.invulnerable>0)return;game.health-=amount;game.player.invulnerable=1.5;emit(game.player.pos.x,game.player.pos.y,'#ff8e91',`−${amount} ♥`);chirp('hurt');}
function step(dt){game.ambientTime+=dt;const active=game.state==='playing';const menu=game.state==='menu';if(!active&&!menu)return;if(active)game.time+=dt;game.boosting=active&&(game.keys.has(' ')||game.pointerBoost)&&game.boost>2;game.player.maxSpeed=game.boosting?420:245;game.boost=clamp(game.boost+(game.boosting?-35:19)*dt,0,100);game.player.invulnerable=Math.max(0,game.player.invulnerable-dt);if(active&&!game.sandbox)game.health-=(game.healthDrain??1.05)*dt;
  const c={...game,dt,mode:game.mode};if(active){game.player.advance(dt,c);if(!game.player.airborne)game.player.resolveObstacles(game.obstacles);if(game.autoZoom)game.player.constrainToWorld(game.w,game.h,game.waterY);else{game.player.pos.x=clamp(game.player.pos.x,26,game.w-26);game.player.pos.y=clamp(game.player.pos.y,game.player.airborne?-700:(game.waterY?game.waterY+game.player.radius*.25:30),game.h-30);}}
  // Toutes les forces utilisent l'état de début du pas (pas de biais par ordre).
  fishGrid.rebuild(game.fish);
  const forces=game.fish.map(f=>{c.neighbors=fishGrid.query(f.pos,110);f.trackHistory=!!game.params.trails;f.maxSpeed=game.params.maxSpeed*f.dna[0]*[1, .85,1.2][f.type]*(f.creature==='turtle'?.65:f.creature==='ray'?.8:1);f.maxForce=game.params.maxForce;f.manager.changeWeight('separation',game.params.separation).changeWeight('alignment',game.params.alignment).changeWeight('cohesion',game.params.cohesion);return f.manager.getSteeringForce(c);});
  c.neighbors=null;
  game.fish.forEach((f,i)=>{f.applyForce(forces[i]);f.update(dt);f.resolveObstacles(game.obstacles);f.edges(game.w,game.h);f.age+=dt;if(game.params.genetic){f.health-=.65*dt;for(const p of game.food){if(f.pos.dist(p)<13){f.health=Math.min(100,f.health+22);const np=safePosition();p.x=np.x;p.y=np.y;break;}}for(const j of game.jellies){if(f.pos.dist(j.pos)<24)f.health-=15*dt;}}});
  for(const e of game.enemies){e.applyForce(e.manager.getSteeringForce(c));e.update(dt);e.resolveObstacles(game.obstacles);e.edges(game.w,game.h);}for(const j of game.jellies){j.applyForce(j.manager.getSteeringForce(c));j.update(dt);j.edges(game.w,game.h);}
  if(active){let kept=[];for(const f of game.fish){if(game.mode!=='snake'&&game.mode!=='leader'&&(!game.canEatPrey||game.canEatPrey(f))&&f.pos.dist(game.player.pos)<game.player.radius+f.radius){eatFish(f);continue;}if(game.params.genetic&&f.health<=0){game.food.push(f.pos.copy());if(game.food.length>50)game.food.shift();continue;}let eaten=false;for(const e of game.enemies){if(e.pos.dist(f.pos)<e.radius+f.radius){emit(f.pos.x,f.pos.y,'#f09b88');eaten=true;break;}}if(!eaten)kept.push(f);}game.fish=kept;for(const e of game.enemies){if(e.pos.dist(game.player.pos)<e.radius+game.player.radius){if(game.onEnemyContact)game.onEnemyContact(e);else{hurt(18);const away=Vec.sub(game.player.pos,e.pos).setMag(50);game.player.pos.add(away);}}}for(const j of game.jellies){if(j.pos.dist(game.player.pos)<j.radius+game.player.radius)hurt(12);}game.spawnTimer+=dt;if(game.spawnTimer>.6){game.spawnTimer=0;if(game.fish.length<game.params.population){const p=safePosition();if(game.params.genetic&&game.fish.length){const eligible=[...game.fish].sort((a,b)=>b.health-a.health).slice(0,Math.max(1,Math.ceil(game.fish.length*.3)));const parent=eligible[Math.floor(Math.random()*eligible.length)];const child=parent.offspring(p.x,p.y);game.generation=Math.max(game.generation,child.generation);game.fish.push(child);}else game.fish.push(new Fish(p.x,p.y,Math.floor(rand(0,3))));}}if(game.health<=0)finish(false);}
  for(const p of game.particles)p.tick(dt);game.particles=game.particles.filter(p=>p.life>0);updateCamera(dt);}
function updateHUD(){const time=Math.floor(game.time);$('score').textContent=String(game.score).padStart(4,'0');$('best').textContent=game.best;$('combo').textContent=game.combo>1&&game.time-game.lastEat<2.5?`COMBO ×${game.combo}`:'';$('healthValue').textContent=`${Math.ceil(Math.max(0,game.health))}%`;$('healthBar').style.width=`${clamp(game.health,0,100)}%`;$('healthBar').style.background=game.health<30?'#fa8e88':'#7de6ce';$('boostValue').textContent=`${Math.ceil(game.boost)}%`;$('boostBar').style.width=`${game.boost}%`;$('time').textContent=`${String(Math.floor(time/60)).padStart(2,'0')}:${String(time%60).padStart(2,'0')}`;$('level').textContent=`NIV. ${String(game.level).padStart(2,'0')}`;$('fishCount').textContent=game.fish.length;$('predCount').textContent=game.enemies.length;$('fps').textContent=`${Math.round(fps)} FPS`;$('depth').textContent=`${Math.round(8+game.player.pos.y/32)} M`;$('modeBadge').textContent=game.sandbox?`EXPLORATION · ${game.mode.toUpperCase()}`:'MODE CHASSE';$('zoneSub').textContent=game.params.genetic?`ÉCOSYSTÈME · GÉNÉRATION ${game.generation}`:'EAUX TROPICALES · 24°C';const missions=[{name:'Le festin du récif',current:game.eaten,max:25,unit:'poissons',icon:'◇'},{name:'L’instinct du chasseur',current:game.score,max:1000,unit:'points',icon:'⌁'},{name:'L’art de la survie',current:Math.floor(game.time),max:90,unit:'secondes',icon:'◷'}];let done=0;$('missions').innerHTML=missions.map(m=>{const complete=m.current>=m.max;if(complete)done++;return `<div class="mission ${complete?'done':''}"><div class="mission-icon">${complete?'✓':m.icon}</div><div class="mission-content">${m.name}<small>${Math.min(m.current,m.max)} / ${m.max} ${m.unit}</small><div class="mission-progress"><i style="width:${Math.min(100,m.current/m.max*100)}%"></i></div></div></div>`;}).join('');$('missionCount').textContent=`${done} / 3`;}
function resize(){const rect=$('ocean').getBoundingClientRect();game.width=rect.width;game.height=rect.height;const budget=graphics.economy?850000:graphics.pixelBudget,dpr=Math.max(.65,Math.min(devicePixelRatio||1,graphics.economy?1:1.25,Math.sqrt(budget/(rect.width*rect.height))));canvas.width=rect.width*dpr;canvas.height=rect.height*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);if(game.autoZoom){updateZoom(0,true);updateCamera(0,true);}}
/** Coordonnées écran et monde : le HUD ne change pas d'échelle, seul l'océan. */
function viewportWorld(){const z=game.zoom||1;return {w:game.width/z,h:game.height/z};}
function worldToScreen(p){return Vec.sub(p,game.camera).mult(game.zoom||1);}
function screenToWorld(p){return Vec.add(p.copy().div(game.zoom||1),game.camera);}
function applyWorldTransform(){ctx.scale(game.zoom||1,game.zoom||1);ctx.translate(-game.camera.x,-game.camera.y);}
function updateZoom(dt,snap=false){
  const desired=game.autoZoom&&game.state!=='menu'?clamp(Math.min(game.width,game.height)*.44/(game.player.radius*5.8),.18,1):1;
  game.zoom=snap?desired:(game.zoom||1)+(desired-(game.zoom||1))*(1-Math.exp(-3.5*dt));
}
function updateCamera(dt,snap=false){
  const view=viewportWorld();const desired=Vec.sub(game.player.pos,new Vec(view.w*.5,view.h*.5));
  if(snap)game.camera=desired;else game.camera.add(Vec.sub(desired,game.camera).mult(1-Math.exp(-4*dt)));
  game.camera.x=clamp(game.camera.x,0,Math.max(0,game.w-view.w));
  game.camera.y=clamp(game.camera.y,game.waterY?-Math.max(550,view.h*.65):0,Math.max(0,game.h-view.h));
}
function visible(p,r=100){const view=viewportWorld();return p.x>game.camera.x-r&&p.x<game.camera.x+view.w+r&&p.y>game.camera.y-r&&p.y<game.camera.y+view.h+r;}

function shape(points,fill,stroke){ctx.beginPath();ctx.moveTo(...points[0]);for(let i=1;i<points.length;i++)ctx.lineTo(...points[i]);ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.stroke();}}
function ellipse(x,y,rx,ry,fill){ctx.beginPath();ctx.ellipse(x,y,Math.max(.01,rx),Math.max(.01,ry),0,0,Math.PI*2);ctx.fillStyle=fill;ctx.fill();}
function fishArt(f,t){const a=f.vel.heading(),r=f.radius;ctx.save();ctx.translate(f.pos.x,f.pos.y);ctx.rotate(a);const swing=Math.sin(t*8+f.theta)*3;ctx.shadowColor=['#52d8cd66','#ff9e7766','#f9d58077'][f.type];ctx.shadowBlur=0;const palette=[['#7be5d5','#2b9eab'],['#ffbc86','#c96c6e'],['#ffe5a4','#cfa350']][f.type];shape([[-r+2,0],[-r*1.9,swing-r*.8],[-r*1.65,swing+r*.8]],palette[1]);const grad=ctx.createLinearGradient(0,-r,0,r);grad.addColorStop(0,palette[0]);grad.addColorStop(1,palette[1]);ellipse(0,0,r*1.45,r*.7,grad);ctx.shadowBlur=0;shape([[-r*.2,-r*.3],[-r*.6,-r],[r*.7,-r*.3]],palette[1]);ctx.globalAlpha=.45;ellipse(-r*.2,r*.2,r*.5,r*.2,'#fff4d0');ctx.globalAlpha=1;ellipse(r*.8,-r*.15,r*.19,r*.2,'#edf8ef');ellipse(r*.86,-r*.15,r*.1,r*.13,'#173343');ctx.restore();}
function sharkArt(s,t,scaleOverride=1){ctx.save();ctx.translate(s.pos.x,s.pos.y);let a=s.facing??(s.vel.mag()>4?s.vel.heading():0);ctx.rotate(a);const flip=Math.cos(a)<0;if(flip)ctx.scale(1,-1);const scale=s.radius/24*scaleOverride;ctx.scale(scale,scale);const tail=Math.sin(t*6+s.theta)*8;const player=s.isPlayer,gold=!!s.golden;ctx.shadowColor=player?'#5de6d74a':'#fa777744';ctx.shadowBlur=graphics.glow?10:0;shape([[-39,0],[-68,-28+tail],[-58,tail],[-69,29+tail]],gold?'#bd8d30':player?'#408f9d':'#a84f5b');shape([[-8,-13],[0,-47],[21,-10]],gold?'#d9ab48':player?'#4e9dae':'#bb6671');shape([[-9,12],[2,39],[25,15]],gold?'#b78229':player?'#4590a0':'#a35164');const body=ctx.createLinearGradient(0,-23,0,25);body.addColorStop(0,gold?'#ffe491':player?'#91d3d8':'#e79593');body.addColorStop(.45,gold?'#dab048':player?'#559eae':'#b96173');body.addColorStop(.65,gold?'#efce75':player?'#93bec6':'#d3a4ac');body.addColorStop(1,gold?'#fff2c7':player?'#e7eded':'#e9d4d3');ctx.beginPath();ctx.moveTo(-47,0);ctx.bezierCurveTo(-25,-30,19,-26,50,-5);ctx.quadraticCurveTo(65,2,44,13);ctx.bezierCurveTo(13,29,-24,26,-47,0);ctx.fillStyle=body;ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle=player?'#d7faff66':'#ffd6ca44';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(-28,-10);ctx.quadraticCurveTo(15,-29,46,-8);ctx.stroke();shape([[-5,0],[9,24],[25,12]],player?'#497e90':'#9f5063');for(let i=0;i<3;i++){ctx.strokeStyle='#183d5080';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(13-i*5,-6);ctx.quadraticCurveTo(10-i*5,1,14-i*5,6);ctx.stroke();}ellipse(34,-6,4,4.3,'#e5f6ed');ellipse(35,-6,2.3,2.9,'#0c2533');ellipse(35.7,-7.1,.8,.8,'white');ctx.strokeStyle='#284554';ctx.lineWidth=1.2;ctx.beginPath();ctx.moveTo(34,9);ctx.quadraticCurveTo(46,13,54,4);ctx.stroke();for(let i=0;i<4;i++)shape([[39+i*3,10],[40+i*3,13],[42+i*3,9.5]],'#f1f5e7');if(player&&game.boosting){ctx.globalAlpha=.6;for(let i=0;i<6;i++)ellipse(-60-rand(0,35),rand(-18,18),rand(1,3),rand(1,3),'#9bf0de');}ctx.restore();}
function jellyArt(j,t){ctx.save();ctx.translate(j.pos.x,j.pos.y);const pulse=1+Math.sin(t*2+j.phase)*.1;ctx.scale(pulse,pulse);ctx.shadowColor='#b6a1f8';ctx.shadowBlur=graphics.glow?10:0;const g=ctx.createRadialGradient(0,0,1,0,0,24);g.addColorStop(0,'#d9c8ffb0');g.addColorStop(1,'#9180d433');ctx.beginPath();ctx.ellipse(0,0,20,15,0,Math.PI,0);ctx.quadraticCurveTo(10,9,0,4);ctx.quadraticCurveTo(-9,9,-20,0);ctx.fillStyle=g;ctx.fill();ctx.shadowBlur=0;for(let i=0;i<5;i++){ctx.strokeStyle='#c9b2f87a';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(-13+i*6,4);ctx.bezierCurveTo(-20+i*6+Math.sin(t*2+i)*6,15,-7+i*6,22,-14+i*6+Math.sin(t*2+i)*7,37);ctx.stroke();}ctx.restore();}
function coral(x,y,scale,kind,t){ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);ctx.strokeStyle=kind===0?'#215765':kind===1?'#3c7781':'#8b6e7966';ctx.lineCap='round';const sway=Math.sin(t*.7+x)*4;for(let i=0;i<5;i++){const endX=(i-2)*13+sway,endY=-28-Math.sin(i*2+x)*20;ctx.lineWidth=4-i*.35;ctx.beginPath();ctx.moveTo(0,0);ctx.quadraticCurveTo((i-2)*2,-18,endX,endY);ctx.stroke();ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(endX*.7,endY*.65);ctx.lineTo(endX+10,endY*.8-12);ctx.stroke();if(kind===1){ellipse(endX,endY,2.5,2.5,'#92c9b775');}}ctx.restore();}
function rockArt(o){ctx.save();ctx.translate(o.pos.x,o.pos.y);const r=o.radius;ctx.shadowColor='#001c2c';ctx.shadowBlur=0;ctx.shadowOffsetY=15;ctx.beginPath();for(let i=0;i<9;i++){const a=i/9*Math.PI*2;const rr=r*(.91+.07*Math.sin(i*10+o.seed));const x=Math.cos(a)*rr,y=Math.sin(a)*rr*.9;if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);}ctx.closePath();const g=ctx.createLinearGradient(-r,-r,r,r);const stone=game.sceneStyle?.stone||['#426879','#214657','#102f42'];g.addColorStop(0,stone[0]);g.addColorStop(.4,stone[1]);g.addColorStop(1,stone[2]);ctx.fillStyle=g;ctx.fill();ctx.shadowBlur=0;ctx.shadowOffsetY=0;ctx.strokeStyle='#9bc5bf18';ctx.stroke();shape([[-r*.6,-r*.4],[-r*.1,-r*.8],[r*.3,-r*.2]],'#74948e12');ctx.strokeStyle='#081f3166';ctx.beginPath();ctx.moveTo(-r*.1,-r*.8);ctx.lineTo(r*.1,-r*.2);ctx.lineTo(-r*.25,r*.2);ctx.stroke();coral(-r*.5,-r*.5,.7,1,game.ambientTime);coral(r*.4,-r*.45,.45,2,game.ambientTime);ctx.restore();}
function line(a,b,color,width=1,dash=[]){ctx.beginPath();ctx.setLineDash(dash);ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke();ctx.setLineDash([]);}
function ring(p,r,color){ctx.beginPath();ctx.arc(p.x,p.y,r,0,Math.PI*2);ctx.strokeStyle=color;ctx.lineWidth=1;ctx.stroke();}
function debugArt(v){ring(v.pos,v.radius,'#ffffff55');line(v.pos,Vec.add(v.pos,v.vel.copy().mult(.45)),'#7de6ce',2);if(v.predicted){line(v.pos,v.predicted,'#edc57f88',1,[4,4]);ring(v.predicted,4,'#edc57f');}if(v.pathProjection)ring(v.pathProjection,4,'#a6bfff');if(v.avoidTarget){line(v.pos,v.avoidTarget.pos,'#ff9d93',2);ring(v.avoidTarget.pos,v.avoidTarget.radius+v.radius,'#ff9d9344');}ctx.font='8px monospace';ctx.fillStyle='#b8e0dc';ctx.fillText(v.state||'agent',v.pos.x-15,v.pos.y-25);}
function render(){const w=game.width,h=game.height,t=game.ambientTime;ctx.clearRect(0,0,w,h);const bg=ctx.createLinearGradient(0,0,w*.35,h);const water=game.sceneStyle?.water||['#15556a','#0d4054','#052536'];bg.addColorStop(0,water[0]);bg.addColorStop(.38,water[1]);bg.addColorStop(1,water[2]);ctx.fillStyle=bg;ctx.fillRect(0,0,w,h);
  // Rayons lumineux animés et particules : décor calculé, pas d'image externe.
  ctx.save();ctx.globalCompositeOperation='screen';for(let i=0;i<(graphics.economy?2:4);i++){const x=w*.2+i*w*.22+Math.sin(t*.07+i)*35;const grad=ctx.createLinearGradient(x,0,x+w*.15,h);grad.addColorStop(0,'#6dc5c010');grad.addColorStop(1,'#4cbbcf00');shape([[x,-10],[x+w*.04,-10],[x+w*.31,h],[x+w*.15,h]],grad);}ctx.restore();for(const d of (graphics.economy?dust.slice(0,18):dust)){const x=(d.x*w+t*d.speed*2)%w,y=(d.y*h-t*d.speed*1.7%h+h)%h;ellipse(x,y,d.r,d.r,'#c4f1e11e');}for(let i=0;i<7;i++){const x=(w*.13+i*167+Math.sin(t*.15+i)*35)%w,y=(h+35-(t*(9+i)+i*87)%(h+70));ring(new Vec(x,y),2+i%3,'#c9f5f01b');}
  if(game.drawScenery)game.drawScenery();
  ctx.save();applyWorldTransform();if(game.params.vectors||game.mode==='path'){ctx.beginPath();game.path.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.strokeStyle='#8fc7e51a';ctx.lineWidth=56;ctx.stroke();ctx.strokeStyle='#8fc7e566';ctx.lineWidth=1;ctx.setLineDash([8,10]);ctx.stroke();ctx.setLineDash([]);}if(game.params.currents&&game.params.vectors){for(let x=Math.max(0,Math.floor(game.camera.x/100)*100);x<Math.min(game.w,game.camera.x+viewportWorld().w);x+=100)for(let y=Math.max(0,Math.floor(game.camera.y/100)*100);y<Math.min(game.h,game.camera.y+viewportWorld().h);y+=100){const a=(Math.sin(x*.004+t*.15)+Math.cos(y*.005-t*.1))*2;line(new Vec(x,y),Vec.add(new Vec(x,y),Vec.fromAngle(a).mult(22)),'#78dbd733');}}
  for(const p of game.food){if(visible(p,10)){ctx.shadowBlur=0;ctx.shadowColor='#88e8b4';ellipse(p.x,p.y,2,2,'#b3eccb70');ctx.shadowBlur=0;}}for(const o of game.obstacles)if(visible(o.pos,o.radius+50))rockArt(o);for(const j of game.jellies)if(visible(j.pos,70))jellyArt(j,t);if(game.params.trails){for(const f of game.fish){if(!visible(f.pos))continue;for(let i=1;i<f.history.length;i++){if(f.history[i].dist(f.history[i-1])<50)line(f.history[i-1],f.history[i],`rgba(120,220,210,${i/f.history.length*.18})`);}}}for(const f of game.fish)if(visible(f.pos))fishArt(f,t);for(const s of game.enemies)if(visible(s.pos,100))sharkArt(s,t);if(game.state!=='menu'&&!game.player.airborne&&!(game.waterY&&game.player.pos.y<game.waterY+game.player.radius*2)){if(game.player.invulnerable>0)ctx.globalAlpha=.4+Math.sin(t*30)*.25;sharkArt(game.player,t);ctx.globalAlpha=1;ring(game.player.pos,game.player.radius+18,'#7de6ce19');}
  for(const p of game.particles){ctx.globalAlpha=p.life;if(p.text){ctx.font='600 17px Space Grotesk, sans-serif';ctx.fillStyle=p.color;ctx.fillText(p.text,p.pos.x,p.pos.y);}else ellipse(p.pos.x,p.pos.y,p.radius,p.radius,p.color);ctx.globalAlpha=1;}if(game.params.vectors){ring(game.player.pos,game.params.vision,'#7de6ce22');debugArt(game.player);for(const f of game.fish)if(visible(f.pos))debugArt(f);for(const e of game.enemies)if(visible(e.pos))debugArt(e);}ctx.restore();
  // Silhouettes du récif en premier plan.
  const floor=ctx.createLinearGradient(0,h-90,0,h);floor.addColorStop(0,'#031d2a00');floor.addColorStop(1,'#041d2bcc');ctx.fillStyle=floor;ctx.fillRect(0,h-100,w,100);for(let i=0;i<(graphics.economy?0:7);i++){const x=(i*211-game.camera.x*.2+w*3)%(w+100)-50;coral(x,h+10,.9+(i%3)*.55,i%3,t);}if(game.health<28&&game.state==='playing'&&!game.sandbox){const red=ctx.createRadialGradient(w/2,h/2,h*.2,w/2,h/2,h*.75);red.addColorStop(0,'#ff434300');red.addColorStop(1,'#f85d6038');ctx.fillStyle=red;ctx.fillRect(0,0,w,h);}drawMinimap(w,h);}
function drawMinimap(w,h){if(game.state==='menu'||w<450)return;const mw=115,mh=73,x=w-mw-26,y=h-mh-70;ctx.fillStyle='#031d2c88';ctx.strokeStyle='#7de6ce22';ctx.lineWidth=1;ctx.beginPath();ctx.roundRect(x,y,mw,mh,5);ctx.fill();ctx.stroke();for(const o of game.obstacles)ellipse(x+o.pos.x/game.w*mw,y+o.pos.y/game.h*mh,o.radius/game.w*mw,o.radius/game.h*mh,'#69949355');for(const e of game.enemies)ellipse(x+e.pos.x/game.w*mw,y+e.pos.y/game.h*mh,2,2,'#ec8a8a');ellipse(x+game.player.pos.x/game.w*mw,y+game.player.pos.y/game.h*mh,2.5,2.5,'#7de6ce');ctx.strokeStyle='#7de6ce44';ctx.strokeRect(x+game.camera.x/game.w*mw,y+game.camera.y/game.h*mh,viewportWorld().w/game.w*mw,viewportWorld().h/game.h*mh);}
function frame(now){const raw=(now-frameTime)/1000||.016;frameTime=now;const dt=Math.min(raw,.05);fps=fps*.95+(1/Math.max(.001,raw))*.05;step(dt);render();if(typeof tickTrainer==='function')tickTrainer(dt);uiTimer+=dt;if(uiTimer>.15){uiTimer=0;updateHUD();}requestAnimationFrame(frame);}
function pointerPosition(e){const r=canvas.getBoundingClientRect();game.mouse=new Vec(e.clientX-r.left,e.clientY-r.top);game.target=screenToWorld(game.mouse);}
canvas.addEventListener('pointermove',e=>{if(e.pointerType==='touch'&&!game.pointerActive)return;pointerPosition(e);});canvas.addEventListener('pointerdown',e=>{game.pointerActive=true;canvas.setPointerCapture(e.pointerId);pointerPosition(e);canvas.focus();});canvas.addEventListener('pointerup',()=>{game.pointerActive=false;});canvas.addEventListener('pointercancel',()=>{game.pointerActive=false;game.pointerBoost=false;});canvas.addEventListener('dblclick',()=>{if(game.state==='playing'){game.pointerBoost=true;setTimeout(()=>game.pointerBoost=false,800);}});
window.addEventListener('keydown',e=>{if(e.target.matches('input,select,textarea')||['lab','guide','garage','missionDialog','mapDialog','levelsDialog'].some(id=>$(id).open))return;const key=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(key))e.preventDefault();game.keys.add(key);if(e.repeat)return;if(key==='p'||key==='escape')pause();if(key==='v'){game.params.vectors=!game.params.vectors;$('vectors').checked=game.params.vectors;}// V et X évitent les conflits avec les déplacements ZQSD / WASD.
if(key==='l')setMode('leader');if(key==='x')setMode('snake');if(key==='n')setMode('flock');if(key==='o'&&game.state==='playing'){const p=screenToWorld(game.mouse);if(p.dist(game.player.pos)>110){game.obstacles.push(new Obstacle(clamp(p.x,50,game.w-50),clamp(p.y,50,game.h-50),rand(30,55)));toast('Rocher ajouté · les agents adaptent leur trajectoire');}}});window.addEventListener('keyup',e=>game.keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{game.keys.clear();if(game.state==='playing')pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&game.state==='playing')pause();});
$('startBtn').onclick=()=>start(false);$('sandboxBtn').onclick=()=>start(true);$('againBtn').onclick=()=>start(false);$('exploreBtn').onclick=()=>start(true);$('restartBtn').onclick=()=>start(game.sandbox);$('resumeBtn').onclick=pause;$('pauseBtn').onclick=pause;$('playTab').onclick=()=>{if(game.state==='menu')start(false);else if(game.state==='paused')pause();};$('debugBtn').onclick=()=>{game.params.vectors=!game.params.vectors;$('vectors').checked=game.params.vectors;toast(game.params.vectors?'Vision IA activée : vitesse en vert, prédiction en or':'Vision IA désactivée');};$('soundBtn').onclick=()=>{sound=!sound;$('soundBtn').style.color=sound?'#7de6ce':'';$('soundBtn').title=sound?'Couper le son':'Activer le son';if(sound)chirp();};
let resumeAfterDialog=false;function openDialog(id){resumeAfterDialog=game.state==='playing';if(resumeAfterDialog){game.state='paused';}game.keys.clear();$(id).showModal();}function closeDialog(id){$(id).close();if(resumeAfterDialog){game.state='playing';show('pauseScreen',false);}resumeAfterDialog=false;}
$('guideBtn').onclick=()=>openDialog('guide');$('labBtn').onclick=()=>openDialog('lab');document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>closeDialog(b.dataset.close));for(const id of ['lab','guide','garage','missionDialog','mapDialog','levelsDialog']){$(id).addEventListener('cancel',e=>{e.preventDefault();closeDialog(id);});}
window.addEventListener('resize',resize);resize();reset();requestAnimationFrame(frame);
